TOOL_CALL_VALIDATION = {
  "require_non_empty_tool": True,
  "allowed_tool_names": ["search_docs", "get_order", "list_orders", "calculator", "convert_units", "read_memory"],
  "on_invalid_tool_call": "return_corrective_error",
  "corrective_error_template": (
    "INVALID_TOOL_CALL: the 'tool' field was empty or unknown. "
    "You must emit a tool call with a non-empty 'tool' field set to one of: "
    "{allowed_tools}. Do NOT put the tool name in 'action'. "
    "Expected format: {{\"action\": \"call\", \"tool\": \"<tool_name>\", \"args\": {{...}}}}"
  ),
  "max_consecutive_identical_invalid_calls": 1,
  "on_repeated_invalid_call": "abort_with_diagnostic"
}

# Dispatcher validation logic (apply in tool dispatch entrypoint):
def validate_tool_call(call, allowed_tools, state):
    tool = (call.get("tool") or "").strip()
    if not tool or tool not in allowed_tools:
        state.invalid_call_count += 1
        if state.invalid_call_count > TOOL_CALL_VALIDATION["max_consecutive_identical_invalid_calls"]:
            raise ToolCallAbort("Repeated invalid tool call; aborting with diagnostic")
        return ToolCallError(
            TOOL_CALL_VALIDATION["corrective_error_template"].format(
                allowed_tools=", ".join(allowed_tools)
            )
        )
    state.invalid_call_count = 0
    return None  # valid, proceed to dispatch

