def get_order(order_id: str) -> dict:
    record = _load_order(order_id)
    if record is None:
        return {
            "status": "NOT_FOUND",
            "order_id": order_id,
            "message": f"Order {order_id} does not exist. Do not retry get_order with this id. Use list_orders to verify the id or ask the user to confirm.",
            "retryable": False,
        }
    if record.get("state") == "PENDING":
        return {
            "status": "PENDING",
            "order_id": order_id,
            "message": f"Order {order_id} is still being processed and cannot be resolved synchronously. Do not call get_order again for this id in this turn. Report the pending status to the user or try a different tool.",
            "retryable": False,
            "terminal": True,
        }
    return {
        "status": "OK",
        "order_id": order_id,
        "record": record,
        "retryable": False,
    }

